import { HugeiconsIcon } from "@hugeicons/react";
import CreditCardIcon from "@hugeicons/core-free-icons/CreditCardIcon";
import LogOutIcon from "@hugeicons/core-free-icons/LogOutIcon";
import Settings01Icon from "@hugeicons/core-free-icons/Settings01Icon";
import UserIcon from "@hugeicons/core-free-icons/UserIcon";

import { Button } from "@/registry/erbium/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
  DropdownMenuList,
} from "@/registry/erbium/ui/dropdown-menu";

export function DropdownMenuIcons() {
  return (
    <DropdownMenu>
      <DropdownMenuTrigger render={<Button variant="outline" />}>Open</DropdownMenuTrigger>
      <DropdownMenuContent>
        <DropdownMenuList>
          <DropdownMenuItem>
            <HugeiconsIcon icon={UserIcon} />
            Profile
          </DropdownMenuItem>
          <DropdownMenuItem>
            <HugeiconsIcon icon={CreditCardIcon} />
            Billing
          </DropdownMenuItem>
          <DropdownMenuItem>
            <HugeiconsIcon icon={Settings01Icon} />
            Settings
          </DropdownMenuItem>
          <DropdownMenuSeparator />
          <DropdownMenuItem variant="error">
            <HugeiconsIcon icon={LogOutIcon} />
            Log out
          </DropdownMenuItem>
        </DropdownMenuList>
      </DropdownMenuContent>
    </DropdownMenu>
  );
}

import { DropdownMenuIcons } from "../examples/dropdown-menu-icons";

const Example = () => <DropdownMenuIcons />;

export default Example;
